/**
 * Focuses the next, previous, first or last of `selector`'s matches inside
 * `container`, counting from the one that is or holds `from`. Returns whether
 * `action` was a move and an item took focus; any other action, or a list with
 * no items, moves nothing.
 */
export const moveFocus = (container, selector, action, from) => {
    if (action !== "next" && action !== "previous" && action !== "first" && action !== "last")
        return false;
    const items = [...container.querySelectorAll(selector)];
    if (items.length === 0)
        return false;
    const at = items.findIndex((item) => from !== null && (item === from || item.contains(from)));
    const index = action === "first"
        ? 0
        : action === "last"
            ? items.length - 1
            : action === "next"
                ? Math.min(at + 1, items.length - 1)
                : Math.max(at - 1, 0);
    items[index].focus();
    return true;
};
